func (c Container) RearmPostInstall(ctx context.Context, deploymentID, accountID string) error {
	if err := c.RequirePostInstallCapabilities(ctx, deploymentID); err != nil {
		return err
	}
	tx, err := c.DB.BeginTx(ctx, &sql.TxOptions{})
	if err != nil {

}
