	_ = c.DB.QueryRowContext(ctx, `SELECT EXISTS(SELECT 1 FROM account_proxy_pool ap JOIN proxies p ON p.id=ap.proxy_id WHERE ap.account_id=$1 AND ap.proxy_id=$2::uuid AND ap.enabled=true AND p.status='healthy')`, accountID, active).Scan(&usable)
}
if usable {
	return nil
}
var next string

err := c.DB.QueryRowContext(ctx, `SELECT p.id::text FROM account_proxy_pool ap JOIN proxies p ON p.id=ap.proxy_id WHERE ap.account_id=$1 AND ap.enabled=true AND p.status='healthy' ORDER BY ap.priority,ap.proxy_id LIMIT 1`, accountID).Scan(&next)
if errors.Is(err, sql.ErrNoRows) {
	return ErrNetworkNotReady
}
if err != nil {
	return err
}
tx, err := c.DB.BeginTx(ctx, nil)

if err != nil {
	return err
}
defer tx.Rollback()
if _, err = tx.ExecContext(ctx, `SELECT pg_advisory_xact_lock(hashtextextended($1,0))`, "account-proxy:"+accountID); err != nil {
